import { zodResolver } from '@hookform/resolvers/zod';
import { Select, TextField, Textarea } from '@navikt/ds-react';
import React, { RefObject, useMemo } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { z } from 'zod';
import { selectFeature } from '../../../feature/feature-selector';

import { AktivitetStatus, Kanal } from '../../../../datatypes/aktivitetTypes';
import {
    MoteAktivitet,
    Motedeltaker,
    MotedeltakerRolle,
    VeilarbAktivitetType,
} from '../../../../datatypes/internAktivitetTypes';
import { coerceToUndefined } from '../../../../felles-komponenter/skjema/datovelger/common';
import ControlledDatePicker from '../../../../felles-komponenter/skjema/datovelger/ControlledDatePicker';
import { beregnFraTil, beregnKlokkeslettVarighet } from '../../aktivitet-util';
import AktivitetFormHeader from '../AktivitetFormHeader';
import CustomErrorSummary from '../CustomErrorSummary';
import LagreAktivitetKnapp from '../LagreAktivitetKnapp';
import HuskVarsleBruker from './HuskVarsleBruker';
import VideoInfo from './VideoInfo';
import { endOfDay, format, subDays } from 'date-fns';
import { TZDate } from '@date-fns/tz';
import { NORSK_TIDSSONE } from '../../../../utils/dateUtils';
import { useHilsenVeilederTekst } from '../samtalereferat/useHilsenVeilederTekst';
import { FeltEndret } from '../../../../analytics/analytics-taxonomy-events';
import { logEndringAvtaltMote } from '../../../../analytics/analytics';
import { useSelector } from 'react-redux';
import { selectVeilederNavn } from '../../../veileder/veileder-selector';
import { selectBrukerFulltNavn } from '../../aktivitet-slice';
import Deltakere from './Deltakere';

const schema = (startTekst: string) =>
    z.object({
        tittel: z.string().min(1, 'Du må fylle ut tema for møtet').max(100, 'Du må korte ned teksten til 100 tegn'),
        dato: z
            .date({ error: (issue) => (issue.input == null ? 'Dato må fylles ut' : 'Ikke en gyldig dato') })
            .min(endOfDay(subDays(new Date(), 1)), 'Dato kan ikke være tilbake i tid'),
        klokkeslett: z.string().min(1, 'Du må fylle ut klokkeslett'),
        varighet: z.number({ error: () => 'Du må velge varighet' }), // Blir NaN på default value
        kanal: z.nativeEnum(Kanal, { error: () => 'Du må velge møteform' }),

        adresse: z
            .string()
            .min(1, 'Du må fylle ut møtested eller annen praktisk informasjon')
            .max(255, 'Du må korte ned teksten til 255 tegn'),
        beskrivelse: z
            .string()
            .min(1, 'Du må fylle ut hensikten med møtet')
            .max(5000, 'Du må korte ned teksten til 5000 tegn')
            .refine((val) => val.replace(startTekst, '').trim().length > 0, 'Du må fylle ut hensikten med møtet'),
        forberedelser: z.string().max(500, 'Du må korte ned teksten til 500 tegn').optional(),
        deltakere: z
            .array(
                z.object({
                    navn: z.string().trim(),
                    roller: z.array(z.nativeEnum(MotedeltakerRolle)),
                }),
            )
            .superRefine((deltakere, ctx) => {
                deltakere.forEach((deltaker, index) => {
                    if (index === 0 || deltaker.navn || deltaker.roller.length > 0) {
                        if (!deltaker.navn) {
                            ctx.addIssue({
                                code: z.ZodIssueCode.custom,
                                path: [index, 'navn'],
                                message:
                                    index === 0
                                        ? 'Du må fylle ut navn på veilederen'
                                        : 'Du må fylle ut navn på deltakeren',
                            });
                        }
                        if (deltaker.roller.length === 0) {
                            ctx.addIssue({
                                code: z.ZodIssueCode.custom,
                                path: [index, 'roller'],
                                message: 'Du må velge minst én rolle for deltakeren',
                            });
                        }
                    }
                });
            }),
    });

const varighet = [
    { minutter: 15, tekst: '15 minutter' },
    { minutter: 30, tekst: '30 minutter' },
    { minutter: 45, tekst: '45 minutter' },
    { minutter: 60, tekst: '1 time' },
    { minutter: 90, tekst: '1 time, 30 minutter' },
    { minutter: 120, tekst: '2 timer' },
    { minutter: 150, tekst: '2 timer, 30 minutter' },
    { minutter: 180, tekst: '3 timer' },
    { minutter: 210, tekst: '3 timer, 30 minutter' },
    { minutter: 240, tekst: '4 timer' },
    { minutter: 270, tekst: '4 timer, 30 minutter' },
    { minutter: 300, tekst: '5 timer' },
    { minutter: 330, tekst: '5 timer, 30 minutter' },
    { minutter: 360, tekst: '6 timer' },
    { minutter: 390, tekst: '6 timer, 30 minutter' },
    { minutter: 420, tekst: '7 timer' },
    { minutter: 450, tekst: '7 timer, 30 minutter' },
];

export type MoteAktivitetFormValuesInner = z.infer<ReturnType<typeof schema>>;

export type MoteAktivitetFormValuesOuter = {
    tittel: string;
    kanal: Kanal;
    beskrivelse: string;
    forberedelser?: string | undefined;
    adresse: string;
    fraDato: string;
    tilDato: string;
    status: string | undefined;
    avtalt: boolean;
    motedeltakere: Motedeltaker[];
};

interface Props {
    onSubmit: (data: MoteAktivitetFormValuesOuter) => Promise<void>;
    dirtyRef: RefObject<boolean>;
    aktivitet?: MoteAktivitet;
}

const MoteAktivitetForm = (props: Props) => {
    const { aktivitet, dirtyRef, onSubmit } = props;
    const startTekst = useHilsenVeilederTekst();
    const veilederNavn = useSelector(selectVeilederNavn);
    const fulltNavn = useSelector(selectBrukerFulltNavn);
    const lagretBruker = aktivitet?.motedeltakere?.find((deltaker) =>
        deltaker.roller.includes(MotedeltakerRolle.BRUKER),
    );
    const brukerNavn = fulltNavn?.trim() || lagretBruker?.navn.trim();
    const erMotedeltakereEnabled = useSelector(selectFeature('aktivitetsplan.enableMotedeltakere'));

    const moteTid = aktivitet ? beregnKlokkeslettVarighet(aktivitet) : undefined;

    /* Bruker useMemo fordi dateOrUndefined lager en ny verdi hver render så datepicker kan tro at defaultValue
    endrer seg mellom renders selvom det er samme dato */
    const defaultValues: Partial<MoteAktivitetFormValuesInner> = useMemo(() => {
        const deltakere = (aktivitet?.motedeltakere ?? []).filter(
            (deltaker) => !deltaker.roller.includes(MotedeltakerRolle.BRUKER),
        );
        const veilederIndex = deltakere.findIndex((deltaker) => deltaker.roller.includes(MotedeltakerRolle.VEILEDER));
        const veileder: Motedeltaker =
            veilederIndex >= 0
                ? deltakere[veilederIndex]
                : { navn: veilederNavn ?? '', roller: [MotedeltakerRolle.VEILEDER] };
        return {
            tittel: aktivitet?.tittel,
            klokkeslett: moteTid?.klokkeslett?.replace('.', ':'),
            // Keep field as string since input natively returns string
            varighet: moteTid?.varighet,
            kanal: aktivitet?.kanal,
            adresse: aktivitet?.adresse,
            beskrivelse: aktivitet?.beskrivelse || startTekst,
            forberedelser: aktivitet?.forberedelser ?? undefined,
            dato: coerceToUndefined(aktivitet?.fraDato),
            deltakere: [veileder, ...deltakere.filter((_, index) => index !== veilederIndex)],
        };
    }, [aktivitet, veilederNavn]);
    const avtalt = aktivitet?.avtalt || false;

    const formHandlers = useForm<MoteAktivitetFormValuesInner>({
        defaultValues,
        resolver: zodResolver(schema(startTekst)),
        shouldFocusError: true,
    });
    const {
        register,
        handleSubmit,
        setError,
        watch,
        formState: { errors, isDirty, isSubmitting },
    } = formHandlers;

    if (dirtyRef) {
        dirtyRef.current = isDirty;
    }

    const beskrivelseValue = watch('beskrivelse'); // for <Textarea /> character-count to work
    const forberedelserValue = watch('forberedelser'); // for <Textarea /> character-count to work

    return (
        <form
            autoComplete="off"
            noValidate
            onSubmit={handleSubmit((data) => {
                if (!brukerNavn) {
                    setError('root.brukerNavn', {
                        message: 'Kunne ikke hente brukerens navn. Last siden på nytt og prøv igjen.',
                    });
                    return;
                }
                // eslint-disable-next-line @typescript-eslint/no-unused-vars
                const { klokkeslett, deltakere, ...rest } = data;
                const dto: MoteAktivitetFormValuesOuter = {
                    ...rest,
                    ...beregnFraTil(data),
                    status: aktivitet?.status ?? AktivitetStatus.PLANLAGT,
                    avtalt,
                    motedeltakere: erMotedeltakereEnabled
                        ? [
                              {
                                  ...lagretBruker,
                                  navn: brukerNavn,
                                  roller: lagretBruker?.roller ?? [MotedeltakerRolle.BRUKER],
                              },

                              ...deltakere.filter(
                                  (deltaker) =>
                                      deltaker.navn &&
                                      deltaker.roller.length > 0 &&
                                      !deltaker.roller.includes(MotedeltakerRolle.BRUKER),
                              ),
                          ]
                        : [],
                };
                return onSubmit(dto).then(() => loggEndringer(aktivitet, { ...dto, varighet: data.varighet }));
            })}
        >
            <FormProvider {...formHandlers}>
                <div className="space-y-8">
                    <AktivitetFormHeader aktivitetstype={VeilarbAktivitetType.MOTE_TYPE} />
                    <HuskVarsleBruker avtalt={avtalt} endre={!!aktivitet} />

                    <TextField
                        label="Tema for møtet (obligatorisk)"
                        id={'tittel'}
                        {...register('tittel')}
                        error={errors.tittel && errors.tittel.message}
                    />

                    <div className="flex sm:flex-row flex-col gap-4">
                        <ControlledDatePicker
                            disabledDays={[{ before: new Date() }]}
                            field={{ name: 'dato', required: true, defaultValue: defaultValues?.dato }}
                        />
                        <TextField
                            label="Klokkeslett (obligatorisk)"
                            {...register('klokkeslett')}
                            type="time"
                            error={errors.klokkeslett && errors.klokkeslett.message}
                        />
                    </div>
                    <Deltakere erMotedeltakereEnabled={erMotedeltakereEnabled} brukerNavn={brukerNavn} />
                    <Select
                        label="Varighet (obligatorisk)"
                        {...register('varighet', { valueAsNumber: true })}
                        error={errors.varighet && errors.varighet.message}
                    >
                        <option value="">Velg varighet</option>
                        {varighet.map((item) => (
                            <option value={item.minutter} key={item.minutter}>
                                {item.tekst}
                            </option>
                        ))}
                    </Select>
                    <Select
                        label="Møteform (obligatorisk)"
                        {...register('kanal')}
                        error={errors.kanal && errors.kanal.message}
                    >
                        <option value="">Velg møteform</option>
                        <option value={Kanal.OPPMOTE}>Oppmøte</option>
                        <option value={Kanal.TELEFON}>Telefonmøte</option>
                        <option value={Kanal.INTERNET}>Videomøte</option>
                    </Select>
                    <VideoInfo kanal={watch('kanal')} />

                    <TextField
                        label="Møtested eller annen praktisk informasjon (obligatorisk)"
                        id={'adresse'}
                        {...register('adresse')}
                        error={errors.adresse && errors.adresse.message}
                    />
                    <Textarea
                        label="Hensikt med møtet (obligatorisk)"
                        maxLength={5000}
                        {...register('beskrivelse')}
                        error={errors.beskrivelse && errors.beskrivelse.message}
                        value={beskrivelseValue}
                    />
                    <Textarea
                        label="Forberedelser til møtet (valgfri)"
                        maxLength={500}
                        {...register('forberedelser')}
                        error={errors.forberedelser && errors.forberedelser.message}
                        value={forberedelserValue}
                    />
                    <CustomErrorSummary errors={errors} />
                    <LagreAktivitetKnapp loading={isSubmitting} />
                </div>
            </FormProvider>
        </form>
    );
};

const loggEndringer = (
    aktivitet: MoteAktivitet | undefined,
    moteForm: MoteAktivitetFormValuesOuter & { varighet: number },
) => {
    if (!aktivitet || !aktivitet.avtalt) return;

    const str = (val: string | number | null | undefined) => (val == null ? '' : String(val).trim());
    const origMoteTid = beregnKlokkeslettVarighet(aktivitet);
    const nyFraDato = typeof moteForm.fraDato === 'string' ? new TZDate(moteForm.fraDato, NORSK_TIDSSONE) : undefined;

    const felter: [FeltEndret, () => boolean][] = [
        [FeltEndret.TITTEL, () => str(moteForm.tittel) !== str(aktivitet.tittel)],
        [FeltEndret.ADRESSE, () => str(moteForm.adresse) !== str(aktivitet.adresse)],
        [FeltEndret.BESKRIVELSE, () => str(moteForm.beskrivelse) !== str(aktivitet.beskrivelse)],
        [FeltEndret.FORBEREDELSER, () => str(moteForm.forberedelser) !== str(aktivitet.forberedelser)],
        [FeltEndret.KANAL, () => str(moteForm.kanal) !== str(aktivitet.kanal)],
        [FeltEndret.VARIGHET, () => (Number(moteForm.varighet) || 0) !== (origMoteTid?.varighet ?? 0)],
        [FeltEndret.DATO, () => nyFraDato?.toDateString() !== origMoteTid?.dato?.toDateString()],
        [
            FeltEndret.KLOKKESLETT,
            () => (nyFraDato ? format(nyFraDato, 'HH:mm') : '') !== (origMoteTid?.klokkeslett?.replace('.', ':') ?? ''),
        ],
    ];

    const endredeFelter = felter.filter(([, erEndret]) => erEndret()).map(([felt]) => felt);
    if (endredeFelter.length > 0) {
        logEndringAvtaltMote(endredeFelter);
    }
};

export default MoteAktivitetForm;
